head.script:
scwin.checkVal0 = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_0").getAttribute(scwin.dataColMerge) == 'true';
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_1").getAttribute(scwin.dataColMerge) == 'true';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_2").getAttribute(scwin.dataColMerge) == 'true';
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_3").getAttribute(scwin.dataColMerge) == 'true';
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_0_4").getAttribute(scwin.dataColMerge) == 'true';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 각 컬럼들의 colMerge='true' 인지 확인한다.- In the Source tab, make sure that each column has colMerge = 'true'.
    //Verify 1. colMerge='true'
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal0()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. Emp. / Customer. / Visit. 컬럼들의 upperColumn 이 설정되어 있는지 확인한다. - Emp. / Customer. / Visit. Check that the upperColumns of the columns are set.
    //Verify 2. upperColumn='deptNm' / upperColumn='empNm' / upperColumn='custNm'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'gridView1').cellInfoHash.chk.options.upperColumn == 'deptNm'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'gridView1').cellInfoHash.custNm.options.upperColumn == 'empNm'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'gridView1').cellInfoHash.visitCnt.options.upperColumn == 'custNm'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 브라우저에서 colMerge 가 잘 되었는지 확인한다. (예제 그림 참고)-Make sure that colMerge works fine in your browser. (See illustration)
    //Verify 3. 기존과 다르게 Visit. 컬럼의 5부분이 Merge 되지 않는다.-Unlike the previous visit. The 5 parts of the column are not merged.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'gridView1_cell_3_4').innerText == '5'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    scwin.dataColMerge = WebSquare.util.getDataPrefix("colMerge");
    scwin.dataUpperColumn = WebSquare.util.getDataPrefix("upperColumn");
}
